import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputScanner iscan = new InputScanner(System.in);
        OutputWriter out = new OutputWriter(System.out);
        Solver solver = new Solver();
        solver.process(iscan, out);
        out.flush();
    }

    static class Solver {
        void process(InputScanner iscan, OutputWriter out) {
            final int MOD = 998244353;
            int n = iscan.readInt();
            int k = iscan.readInt();
            int[] coeffs = new int[10];
            for (int i = 0; i < k; i++) {
                coeffs[iscan.readInt()] = 1;
            }

            int[] resPoly = new int[]{1};
            int exp = n / 2;

            while (exp > 0) {
                if ((exp & 1) == 1) {
                    resPoly = polynomialMultiply(resPoly, coeffs, MOD);
                }
                coeffs = polynomialMultiply(coeffs, coeffs, MOD);
                exp >>= 1;
            }

            long ans = 0;
            for (int val : resPoly) {
                ans = (ans + (long)val * val) % MOD;
            }
            out.printLine(ans);
        }

        int[] polynomialMultiply(int[] A, int[] B, int mod) {
            int M = A.length + B.length - 1;
            int size = Math.max(2, Integer.highestOneBit(M - 1) << 1);

            double[] ar = new double[size];
            double[] ai = new double[size];
            for (int i = 0; i < A.length; i++) {
                long val = (A[i] % mod + mod) % mod;
                ar[i] = val & 0x7FFF;
                ai[i] = val >>> 15;
            }
            performFFT(ar, ai, false);

            double[] br = new double[size];
            double[] bi = new double[size];
            for (int i = 0; i < B.length; i++) {
                long val = (B[i] % mod + mod) % mod;
                br[i] = val & 0x7FFF;
                bi[i] = val >>> 15;
            }
            performFFT(br, bi, false);

            double[] cr = new double[size];
            double[] ci = new double[size];
            double[] dr = new double[size];
            double[] di = new double[size];

            for (int i = 0; i < size; i++) {
                int j = (size - i) & (size - 1);

                double A1r = (ar[i] + ar[j]) * 0.5;
                double A1i = (ai[i] - ai[j]) * 0.5;
                double A2r = (ai[i] + ai[j]) * 0.5;
                double A2i = (ar[j] - ar[i]) * 0.5;

                double B1r = (br[i] + br[j]) * 0.5;
                double B1i = (bi[i] - bi[j]) * 0.5;
                double B2r = (bi[i] + bi[j]) * 0.5;
                double B2i = (br[j] - br[i]) * 0.5;

                cr[i] = A1r * B1r - A1i * B1i - A2r * B2i - A2i * B2r;
                ci[i] = A1r * B1i + A1i * B1r + A2r * B2r - A2i * B2i;
                dr[i] = A1r * B2r - A1i * B2i + A2r * B1r - A2i * B1i;
                di[i] = A1r * B2i + A1i * B2r + A2r * B1i + A2i * B1r;
            }

            performFFT(cr, ci, true);
            performFFT(dr, di, true);

            int[] result = new int[M];
            for (int i = 0; i < M; i++) {
                long A_part = Math.round(cr[i]);
                long B_part = Math.round(dr[i]);
                long C_part = Math.round(ci[i]);
                result[i] = (int)((A_part + ((B_part % mod) << 15) + ((C_part % mod) << 30)) % mod);
            }
            return result;
        }

        void performFFT(double[] re, double[] im, boolean inverse) {
            int n = re.length;
            for (int i = 1, j = 0; i < n; i++) {
                int bit = n >> 1;
                for (; (j ^= bit) < bit; bit >>= 1);
                if (i < j) {
                    double tmp = re[i]; re[i] = re[j]; re[j] = tmp;
                    tmp = im[i]; im[i] = im[j]; im[j] = tmp;
                }
            }

            for (int len = 2; len <= n; len <<= 1) {
                double angle = 2 * Math.PI / len * (inverse ? -1 : 1);
                double wlen_re = Math.cos(angle);
                double wlen_im = Math.sin(angle);

                for (int i = 0; i < n; i += len) {
                    double w_re = 1;
                    double w_im = 0;
                    int half = len >>> 1;
                    for (int j = 0; j < half; j++) {
                        double ur = re[i + j];
                        double ui = im[i + j];
                        double vr = re[i + j + half] * w_re - im[i + j + half] * w_im;
                        double vi = re[i + j + half] * w_im + im[i + j + half] * w_re;

                        re[i + j] = ur + vr;
                        im[i + j] = ui + vi;
                        re[i + j + half] = ur - vr;
                        im[i + j + half] = ui - vi;

                        double tmp = w_re * wlen_re - w_im * wlen_im;
                        w_im = w_re * wlen_im + w_im * wlen_re;
                        w_re = tmp;
                    }
                }
            }

            if (inverse) {
                for (int i = 0; i < n; i++) {
                    re[i] /= n;
                    im[i] /= n;
                }
            }
        }
    }

    static class InputScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int cur, len;

        public InputScanner(InputStream stream) {
            this.stream = stream;
        }

        public int readInt() {
            int c = read();
            while (c <= 32) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new RuntimeException();
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        private int read() {
            if (cur >= len) {
                try {
                    len = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                cur = 0;
                if (len <= 0) return -1;
            }
            return buf[cur++] & 0xff;
        }
    }

    static class OutputWriter {
        private PrintWriter writer;

        public OutputWriter(InputStream stream) {
            writer = new PrintWriter(stream);
        }

        public void printLine(Object obj) {
            writer.println(obj);
        }

        public void flush() {
            writer.flush();
        }
    }
}
